-- =====================================================================
-- SSOL Wellness House -- migration: 실천방법 375개 온보딩 적격성 메타데이터
-- (Supabase SQL Editor에 전체를 붙여넣고 Run)
--
-- 2026-09-25: owner가 준 SSOL_375_Practice_Onboarding_Mapping_v1.json(AI가 375개 각각의
-- detail을 검토해 초안으로 만든 매핑, status=HUMAN_REVIEW_REQUIRED)을 그대로 옮긴다.
-- wellness_practices.id/title/detail은 전혀 건드리지 않고, 이 별도 테이블에서 1:1로 연결한다
-- (SSOL_375_Practice_Onboarding_Project_v1.md 5장 '원본 보존' 원칙).
--
-- 중요: 이 데이터는 원본 제목이 없는 상태(detail 텍스트만 보고)에서 AI가 초안으로 태깅한
-- 것이라 review_status가 전부 DRAFT_HUMAN_APPROVAL_REQUIRED 또는(13건) 
-- NEEDS_TITLE_AND_HUMAN_REVIEW다. 실제 필터 로직(lib/onboarding/practiceFilter.ts)은
-- NEEDS_TITLE_AND_HUMAN_REVIEW 13건을 안전하게 제외하고 나머지 362건만 쓴다 -- owner가
-- review_note를 보고 검토해주면 review_status를 'approved'로 바꿔서 반영할 수 있다.
-- 여러 번 실행해도 안전하다.
-- =====================================================================

begin;

create table if not exists public.practice_eligibility (
  practice_id             text primary key references public.wellness_practices (id) on delete cascade,
  audience_mode           text not null,            -- SELF/REL/COUPLE/WORK/PARENT/GENERAL_TITLE_REVIEW
  requires_partner        boolean not null default false,
  requires_childcare      boolean not null default false,
  requires_work           boolean not null default false,
  requires_other_person   boolean not null default false,
  work_context            text not null default 'none', -- none/working_any/coworker_environment
  allowed_primary_activity text[] not null default '{}',
  q4_value_codes          text[] not null default '{}',
  q5_hobby_codes          text[] not null default '{}',
  q6_weekend_codes        text[] not null default '{}',
  q7_focus_codes          text[] not null default '{}',
  q9_exclusion_codes      text[] not null default '{}',
  estimated_min_minutes   smallint,
  estimated_max_minutes   smallint,
  time_evidence           text,
  safety_tags             text[] not null default '{}',
  review_status           text not null default 'DRAFT_HUMAN_APPROVAL_REQUIRED',
  review_note             text,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now()
);

comment on table public.practice_eligibility is
  '375개 실천방법(wellness_practices)의 관계/육아/업무 적격성 + 온보딩 코드 매칭 메타데이터. AI 초안(2026-09-25), review_status로 승인 상태 추적.';

drop trigger if exists practice_eligibility_set_updated_at on public.practice_eligibility;
create trigger practice_eligibility_set_updated_at
  before update on public.practice_eligibility
  for each row execute function public.set_updated_at();

alter table public.practice_eligibility enable row level security;
revoke all on public.practice_eligibility from anon, authenticated;
grant select, insert, update, delete on public.practice_eligibility to service_role;

